SELECT CASE WHEN YEAR(launch_date) < 2024 THEN 'before_2024' WHEN YEAR(launch_date) = 2024 THEN '2024' ELSE 'after_2024' END AS launch_cohort, COUNT(DISTINCT price) AS unique_brands, CONCAT_WS(', ', SORT_ARRAY(COLLECT_SET(brand))) AS brand_values, MIN(price) AS min_price FROM products GROUP BY launch_cohort;
